 6→/**
 7→ * ShutdownOverlay - The "arcade shutdown" visual effect
 8→ *
 9→ * When awareness mode toggles, plays a brief dim→brighten sequence
10→ * that creates the feeling of power cutting and restoring.
11→ *
12→ * Timing:
13→ * - 0-200ms: Dim to peak darkness
14→ * - 200-350ms: Hold at peak
15→ * - 350-600ms: Brighten back
16→ * - Cards start animating around 400ms mark
17→ */
18→export function ShutdownOverlay() {
19→  const { awarenessMode } = usePerception();
20→  const [isAnimating, setIsAnimating] = useState(false);
21→  const [phase, setPhase] = useState<'idle' | 'dimming' | 'holding' | 'brightening'>('idle');
22→  const prevModeRef = useRef(awarenessMode);
23→  const isFirstRender = useRef(true);
24→
25→  useEffect(() => {
26→    // Skip animation on initial render
27→    if (isFirstRender.current) {
28→      isFirstRender.current = false;
29→      prevModeRef.current = awarenessMode;
30→      return;
31→    }
32→
33→    // Only animate when mode actually changes
34→    if (prevModeRef.current !== awarenessMode) {
35→      prevModeRef.current = awarenessMode;
36→
37→      // Start the shutdown sequence
38→      setIsAnimating(true);
39→      setPhase('dimming');
40→
41→      // Phase timing
42→      const holdTimer = setTimeout(() => setPhase('holding'), 200);
43→      const brightenTimer = setTimeout(() => setPhase('brightening'), 350);
44→      const completeTimer = setTimeout(() => {
45→        setPhase('idle');
46→        setIsAnimating(false);
47→      }, 600);
48→
49→      return () => {
50→        clearTimeout(holdTimer);
51→        clearTimeout(brightenTimer);
52→        clearTimeout(completeTimer);
53→      };
54→    }
55→  }, [awarenessMode]);
56→
57→  // Don't render anything when not animating
58→  if (!isAnimating) return null;
59→
60→  // Calculate opacity based on phase
61→  const getOpacity = () => {
62→    switch (phase) {
63→      case 'dimming': return 0.85;
64→      case 'holding': return 0.9;
65→      case 'brightening': return 0;
66→      default: return 0;
67→    }
68→  };
69→
70→  // Calculate transition duration based on phase
71→  const getTransition = () => {
72→    switch (phase) {
73→      case 'dimming': return 'opacity 200ms ease-out';
74→      case 'holding': return 'opacity 50ms ease';
75→      case 'brightening': return 'opacity 250ms ease-in';
76→      default: return 'none';
77→    }
78→  };
79→
80→  return (
81→    <div
82→      style={{
83→        position: 'fixed',
84→        inset: 0,
85→        backgroundColor: '#0a0a0a',
86→        opacity: getOpacity(),
87→        transition: getTransition(),
88→        zIndex: 9999,
89→        pointerEvents: 'none',
90→      }}
91→      aria-hidden="true"
92→    />
93→  );
94→}
