 35→/**
 36→ * Render markdown-style text with basic formatting
 37→ * Supports: **bold**, *italic*, `code`, and links
 38→ */
 39→function renderFormattedText(text: string): React.ReactNode {
 40→  // Split by formatting patterns
 41→  const parts: React.ReactNode[] = [];
 42→  let remaining = text;
 43→  let key = 0;
 44→
 45→  // Process bold (**text**)
 46→  const boldRegex = /\*\*(.+?)\*\*/g;
 47→  // Process italic (*text*)
 48→  const italicRegex = /(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)/g;
 49→  // Process code (`text`)
 50→  const codeRegex = /`(.+?)`/g;
 51→
 52→  // Simple approach: replace patterns with spans
 53→  let processed = remaining
 54→    .replace(boldRegex, '<b>$1</b>')
 55→    .replace(codeRegex, '<code>$1</code>');
 56→
 57→  // Handle italic separately to avoid conflicts with bold
 58→  processed = processed.replace(/(?<!<[^>]*)\*([^*]+)\*(?![^<]*>)/g, '<em>$1</em>');
 59→
 60→  // Convert to React nodes using dangerouslySetInnerHTML for simplicity
 61→  // In production, consider using a proper markdown parser
 62→  return (
 63→    <span
 64→      dangerouslySetInnerHTML={{ __html: processed }}
 65→      style={{
 66→        // Code styling
 67→      }}
 68→    />
 69→  );
 70→}
