 22→const COLUMN_GAP = 89;
 23→const ROW_GAP = 89;
 24→const CARD_GAP = 144;
 25→
 26→// Shared scroll state across all card instances
 27→// This ensures all cards respond consistently to "scroll up from bottom"
 28→let globalHasReachedBottom = false;
 29→let globalScrollingUpFromBottom = false;
 30→let globalLastScrollY = 0;
 31→
 32→/**
 33→ * SIMPLE FADE-UP (Original Style, Scroll-Driven)
 34→ * ───────────────────────────────────────────────
 35→ * Mimics the original CSS fadeUp animation:
 36→ *   opacity: 0 → 1
 37→ *   translateY: 24px → 0
 38→ *   ease-out timing
 39→ *
 40→ * Clean. Simple. No flicker. Just a reveal.
 41→ */
 42→function easeOut(t: number): number {
 43→  // Cubic ease-out: fast start, gentle arrival
 44→  return 1 - Math.pow(1 - t, 3);
 45→}
 46→
 47→function getRevealValues(progress: number): { opacity: number; brightness: number; y: number } {
 48→  const p = Math.max(0, Math.min(1, progress));
 49→  const eased = easeOut(p);
 50→
 51→  return {
 52→    opacity: eased,           // 0 → 1
 53→    brightness: 1,            // constant (no brightness manipulation)
 54→    y: 24 * (1 - eased),      // 24px → 0px
 55→  };
 56→}
