 58→function ScrollAnimatedCard({ project, isMobile }: { project: Project; isMobile: boolean }) {
 59→  const ref = useRef<HTMLDivElement>(null);
 60→  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
 61→  const rafRef = useRef<number>(0);
 62→
 63→  // Per-card: track the maximum progress achieved (for "lock on" behavior)
 64→  const maxProgressRef = useRef(0);
 65→
 66→  useEffect(() => {
 67→    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
 68→    setPrefersReducedMotion(mediaQuery.matches);
 69→    const handleChange = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
 70→    mediaQuery.addEventListener('change', handleChange);
 71→    return () => mediaQuery.removeEventListener('change', handleChange);
 72→  }, []);
 73→
 74→  useEffect(() => {
 75→    const element = ref.current;
 76→    if (!element || prefersReducedMotion) return;
 77→
 78→    const updateAnimation = () => {
 79→      const rect = element.getBoundingClientRect();
 80→      const viewportHeight = window.innerHeight;
 81→      const scrollY = window.scrollY;
 82→      const docHeight = document.documentElement.scrollHeight;
 83→
 84→      // === GLOBAL SCROLL STATE DETECTION ===
 85→      // Detect if we've scrolled to the bottom of the page
 86→      const atBottom = (scrollY + viewportHeight) >= (docHeight - 150);
 87→      if (atBottom) {
 88→        globalHasReachedBottom = true;
 89→      }
 90→
 91→      // Detect scroll direction change after reaching bottom
 92→      // If scrolling UP after hitting bottom, enable reversal
 93→      if (globalHasReachedBottom && scrollY < globalLastScrollY - 50) {
 94→        globalScrollingUpFromBottom = true;
 95→      }
 96→
 97→      // If scrolling back DOWN, disable reversal mode
 98→      if (globalScrollingUpFromBottom && scrollY > globalLastScrollY + 30) {
 99→        globalScrollingUpFromBottom = false;
100→      }
101→
102→      // Reset "reached bottom" if user scrolls back to top area
103→      if (scrollY < viewportHeight) {
104→        globalHasReachedBottom = false;
105→        globalScrollingUpFromBottom = false;
106→      }
107→
108→      globalLastScrollY = scrollY;
109→
110→      // === PER-CARD PROGRESS CALCULATION ===
111→      // Simple fade-up: enters viewport → settles at 30% from top
112→      const startY = viewportHeight;
113→      const endY = viewportHeight * 0.3;
114→
115→      // Calculate raw progress based on scroll position
116→      const currentY = rect.top;
117→      let rawProgress: number;
118→
119→      if (currentY >= startY) {
120→        rawProgress = 0;
121→      } else if (currentY <= endY) {
122→        rawProgress = 1;
123→      } else {
124→        rawProgress = (startY - currentY) / (startY - endY);
125→      }
126→
127→      // === LOCK/UNLOCK LOGIC ===
128→      // Normal: cards lock at their max progress (only get MORE visible)
129→      // After hitting bottom + scrolling up: cards can reverse
130→      let progress: number;
131→
132→      if (globalScrollingUpFromBottom) {
133→        // User is scrolling up from bottom - allow reversal
134→        progress = rawProgress;
135→        maxProgressRef.current = rawProgress;
136→      } else {
137→        // Normal scrolling - cards can only become MORE visible
138→        maxProgressRef.current = Math.max(maxProgressRef.current, rawProgress);
139→        progress = maxProgressRef.current;
140→      }
141→
142→      const values = getRevealValues(progress);
143→
144→      // Directly update DOM for performance (no React re-render)
145→      element.style.opacity = String(values.opacity);
146→      element.style.transform = `translateY(${values.y}px)`;
147→    };
148→
149→    const onScroll = () => {
150→      cancelAnimationFrame(rafRef.current);
151→      rafRef.current = requestAnimationFrame(updateAnimation);
152→    };
153→
154→    // Initial calculation
155→    updateAnimation();
156→
157→    window.addEventListener('scroll', onScroll, { passive: true });
158→    window.addEventListener('resize', updateAnimation, { passive: true });
159→
160→    return () => {
161→      window.removeEventListener('scroll', onScroll);
162→      window.removeEventListener('resize', updateAnimation);
163→      cancelAnimationFrame(rafRef.current);
164→    };
165→  }, [prefersReducedMotion]);
166→
167→  // Reduced motion: simple visibility based on viewport
168→  if (prefersReducedMotion) {
169→    return (
170→      <div ref={ref} style={{ opacity: 1 }}>
171→        <ProjectCard project={project} />
172→      </div>
173→    );
174→  }
175→
176→  return (
177→    <div
178→      ref={ref}
179→      style={{
180→        opacity: 0,
181→        transform: 'translateY(24px)',
182→        willChange: 'opacity, transform',
183→      }}
184→    >
185→      <ProjectCard project={project} />
186→    </div>
187→  );
188→}
